import { useState } from "react";
import { getCurrentWebviewWindow, WebviewWindow } from "@tauri-apps/api/webviewWindow";
import { XIcon } from "lucide-react";
import { Button } from "./ui/Button";
import { FieldLabel } from "./ui/Field";
import { Input } from "./ui/Input";

const HardwareTokenPinInput = () => {
    const [pinValue, setPinValue] = useState("");
    const closeWindow = () => getCurrentWebviewWindow().close();

    async function submitTokenPin(e: React.SubmitEvent) {
        e.preventDefault();
        if(!pinValue || pinValue.trim() === "") return;

        const mainWindow = WebviewWindow.getByLabel("main");
        if(mainWindow) {
            await mainWindow.then((res) => res?.emit("token-pin-submitted", { value: pinValue }));
        }
    }

    return (
        <div>
            <div className="bg-zinc-100 border size-full min-h-screen">
                <div
                    data-tauri-drag-region
                    className="bg-white flex items-center justify-between p-1 select-none"
                >
                    <h1 className="text-sm">
                        Verify User PIN
                    </h1>
                    <Button
                        variant="ghost"
                        size="icon"
                        onClick={closeWindow}
                        tabIndex={-1}
                        className="opacity-50 hover:bg-transparent hover:opacity-100"
                    >
                        <XIcon/>
                    </Button>
                </div>
                <div className="px-2 py-3">
                    <div className="flex gap-6 mb-8">
                        <svg
                            version="1.2"
                            xmlns="http://www.w3.org/2000/svg"
                            viewBox="0 0 256 256"
                            width="40"
                            height="40"
                        >
                            <defs>
                                <image  width="256" height="213" id="img1" href="data:image/png;base64,"/>
                            </defs>
                            <use  href="#img1" x="0" y="18"/>
                        </svg>
                        <h2 className="text-sm">
                            Now Verify User PIN
                        </h2>
                    </div>
                    <form onSubmit={submitTokenPin}>
                        <div className="space-y-3 ps-8 pb-2">
                            <div className="flex gap-3 mt-4">
                                <FieldLabel htmlFor="pin" className="text-nowrap">
                                    User PIN:
                                </FieldLabel>
                                <Input
                                    type="password"
                                    id="pin"
                                    value={pinValue}
                                    onChange={(e) => setPinValue(e.target.value)}
                                    autoFocus
                                    className="border-2 border-slate-800! border-b-slate-200! border-e-slate-200! rounded-none w-full px-1.5 focus-visible:outline-none focus-visible:ring-0"
                                />
                            </div>
                            <div className="flex items-center justify-end gap-2">
                                <Button
                                    type="submit"
                                    variant="ghost"
                                    className="border border-b-2 border-e-2 border-slate-800 rounded-none w-24"
                                    tabIndex={-1}
                                    disabled={pinValue.length < 4}
                                >
                                    Login
                                </Button>
                                <Button
                                    type="button"
                                    variant="ghost"
                                    className="border border-b-2 border-e-2 border-slate-800 rounded-none w-24"
                                    tabIndex={-1}
                                    onClick={closeWindow}
                                >
                                    Cancel
                                </Button>
                            </div>
                        </div>
                    </form>
                </div>
            </div>
        </div>
    );
};

export default HardwareTokenPinInput;